            call_ptr(c, 0x0031_7670, 0x001a_c3c8)?;
            c.g[A2][0] = c.g[V0][0];
            c.g[A0][0] = c.g[S1][0];
            c.g[RA][0] = sx(0x001a_c3d8);
            c.g[A1][0] = 0;
            callee::POPUP_SET_OPTION_TEXT_ID.call(c, 0x001a_c3d8)?;
            c.g[V0][0] = sx(0x80d);
            c.g[A0][0] = c.g[S2][0];
