/// `addiu a, b, off` on a 64-bit register.
#[inline(always)]
pub(crate) fn sub(a: u64, off: u32) -> u64 {
    sx((a as u32).wrapping_sub(off))
}

/// `addu a, b` on 64-bit registers.
#[inline(always)]
pub(crate) fn addu(a: u64, b: u64) -> u64 {
    sx((a as u32).wrapping_add(b as u32))
}

/// `lw_8` at `a`.
