                c.g[S0][0] = lw_8(c, p(c.g[S1][0] as u32, select_persona::HASH));
                c.g[S3][0] = lw_8(c, gp(c, -0xc8));
                call_ptr(c, addr::STR_HASH, 0x001a_d33c)?;
                let matched = c.g[S0][0] == c.g[V0][0];
                c.g[A0][0] = sx(0x0046_0000);
