        c.g[S3][0] = c.g[V1][0];
        frame.save(c, S2, 0x30);
        frame.save(c, S1, 0x40);
        frame.save(c, S0, 0x50);
        frame.save(c, S4, 0x10);
        frame.save_ra(c, 0);
        let idle = c.g[V0][0] == 0;
