                c.g[A2][0] = 0u64;
                c.g[V1][0] = sx((c.g[A0][0] as u32).wrapping_add(c.g[S1][0] as u32));
                c.g[A0][0] = c.g[S1][0];
                c.sw((c.g[V1][0] as u32).wrapping_add(0x118), c.g[V0][0]);
                call_ptr(c, 0x001a39d8, 0x001a39a4)?;
