        Addr(popup.wrapping_add(POPUP_OFF_KEEP)).sw(c, 0);
        c.g[V0][0] = Addr(s0.wrapping_add(NETFE_OFF_POPUP)).lw(c);
        frame.restore(c, S0, 0x10);
        frame.restore_ra(c, 0);
        frame.close(c);
        Ok(())
