                                        c.g[V0][0] = Addr(r32(c, GP).wrapping_sub(0x848)).lw(c);
                                        if same {
                                            break 'h;
                                        }
                                        c.cycles += 13;
                                        c.g[A1][0] = 0x1;
                                        c.g[A0][0] = Addr(r32(c, V0).wrapping_add(0x78)).lw(c);
