                                    c.g[A0][0] = sx((c.g[A0][0] as u32).wrapping_sub(0x2338));
                                    Addr(r32(c, S0).wrapping_add(0xc4)).sw(c, c.g[V0][0]);
                                    call_ptr(c, 0x0031_7670, 0x001b_13dc)?;
                                    c.g[A2][0] = c.g[V0][0];
                                    c.g[A1][0] = 0;
                                    c.g[A0][0] = c.g[S1][0];
                                    OC879_POPUP_CFG_OPTION_TEXT_ID.call(c, 0x001b_13ec)?;
                                    c.g[A0][0] = 0x0046_0000;
