                                c.g[V0][0] = Addr(r32(c, S3).wrapping_add(0x8)).lw(c);
                                c.g[A1][0] = 0;
                                c.g[A0][0] = Addr(r32(c, V0).wrapping_add(0x40)).lh(c);
                                c.g[V1][0] = Addr(r32(c, V0).wrapping_add(0x44)).lw(c);
