                            c.g[A0][0] = c.g[S0][0];
                            call_ptr(c, 0x0026_4f88, 0x001b_1490)?;
                            c.g[A0][0] = Addr(r32(c, S2).wrapping_add(0x6d0)).lw(c);
                            call_ptr(c, 0x0039_a738, 0x001b_1498)?;
