                        c.g[A2][0] = c.g[S2][0];
                        c.g[T1][0] = c.lw((c.g[V1][0] as u32).wrapping_add(0x4));
                        c.g[A3][0] = 0x1;
                        c.g[T0][0] = c.lw(c.g[V1][0] as u32);
