                        c.g[V1][0] = 0x82c;
                        c.g[A1][0] = c.g[V0][0];
                        c.sw((c.g[V0][0] as u32).wrapping_add(0x18), c.g[V1][0]);
                        c.g[V0][0] = c.lw((c.g[S2][0] as u32).wrapping_add(0x40));
                        c.g[V1][0] = c.lw((c.g[V0][0] as u32).wrapping_add(0xd0));
                        c.g[A0][0] = c.lw((c.g[V1][0] as u32).wrapping_add(0x10));
