        c.g[V1][0] = Addr(r32(c, S2)).off(0x69c).lw(c);
        c.g[S3][0] = Addr(r32(c, V1)).off(0x18).lw(c);
        c.g[V0][0] = ((c.g[S3][0] as u32) < 0xa) as u64;
        let slot_ok = c.g[V0][0] != 0;
        c.g[S0][0] = sx(r32(c, V1).wrapping_add(0x74));
