    pub(crate) fn globals_7(c: &mut Cpu, buddy_null: bool) {
        c.bus
            .write32(GAME_GP + 0x238, if buddy_null { 0 } else { DATA + 0x700 });
        c.bus.write32(GAME_GP - 0xc8, DATA + 0x780);
    }

