    /// A scrambled machine at `entry`, with GP as the game has it.
    pub(crate) fn oc874_machine(c: &mut Cpu, seed: u32, entry: u32) {
        let mut r = Rng(0x0874_5eed ^ ((seed as u64) << 16) ^ entry as u64);
        scramble(c, &mut r);
        c.g[GP][0] = GAME_GP as u64;
        c.pc = entry;
    }

