    /// `NetFEState_ShowNetErrorPopup(self, popup_out, owner, event)`: builds a
    /// one-button popup for an online error event; the code at `event+8`
    /// picks the message (about 100 codes through a compare tree). `lock`
    /// formats the account lock text, `down` shows the server text with its
    /// newlines replaced, and `cdev`, `dnsf`, `maut` and unknown codes reset
    /// the online session.
    pub(crate) fn oc904_setup(c: &mut Cpu, seed: u32) {
        let mut r = machine_rt(c, seed, 0x1a_9cc0, 14);
        oc904_install_fakes();
        c.bus.write32(OC904_CTRL, OC904_MAGIC);
        c.bus.write32(OC904_CTRL + 0x14, seed % 4);
        let n = OC904_CODES.len() as u32;
        let k = seed % (n + 3);
        let code = if k < n {
            OC904_CODES[k as usize]
        } else {
            0x7a7a_7a00 + k
        };
        c.bus.write32(OC904_EVENT + 0x8, code);
        c.bus.write32(OC904_EVENT + 0xc, OC904_TEXT + 0x400);
        c.bus.write32(OC904_EVENT + 0x10, OC904_TEXT + 0x800);
        c.bus.write32(
            OC904_SELF + 0x6b8,
            if (seed / n) % 2 == 0 {
                0
            } else {
                OC904_TEXT + 0xc00
            },
        );
        for i in 0..0x20u32 {
            c.bus
                .write8(OC904_TEXT + i, if (i + seed) % 3 == 0 { 0xa } else { 0x61 });
        }
        c.bus.write32(GAME_GP.wrapping_sub(0x848), OC904_WORLD);
        c.bus.write32(OC904_WORLD + 0x8c, OC904_LOCALE);
        let vt = fakes::vtable(c, &mut r, &[0x20]);
        c.bus.write32(OC904_LOCALE + 0x4, vt);
        // The `down` case keeps its string object on the stack: [sp] is the text.
        let sp = ssx3_ee_rt::cpu::reg::SP;
        let frame = (c.g[sp][0] as u32).wrapping_sub(0xb0);
        c.bus.write32(frame, OC904_TEXT);
        // Comm system (gp-0x238) and the buddy manager (gp+0x238).
        c.bus
            .write32(GAME_GP.wrapping_sub(0x238), OC904_SELF + 0x800);
        c.bus.write32(OC904_SELF + 0x800 + 0x1c, 0xffff_ffff);
        c.bus.write32(
            GAME_GP.wrapping_add(0x238),
            if seed % 5 == 0 { 0 } else { OC904_SELF + 0x900 },
        );
        c.pc = 0x001a_9cc0;
        c.g[A0][0] = OC904_SELF as u64;
        c.g[A1][0] = OC904_POPUP_OUT as u64;
        c.g[A3][0] = OC904_EVENT as u64;
    }

    #[test]
    fn net_fe_state_show_net_error_popup_matches() {
        let seeds = 330;
        check(
            ee::s03::f_001a9cc0__generated,
            net_fe_state_show_net_error_popup,
            seeds,
            &oc904_setup,
        );
        let mut seen = std::collections::BTreeSet::new();
        for seed in 0..seeds {
            let mut c = fresh();
            oc904_setup(&mut c, seed);
            let before = c.cycles;
            run_generated(&mut c, ee::s03::f_001a9cc0__generated);
            seen.insert(c.cycles - before);
        }
        assert!(seen.len() >= 20, "only {} distinct paths", seen.len());
    }

    pub(crate) const OC905_SELF: u32 = DATA + 0x20_0000;

    pub(crate) const OC905_SCREEN: u32 = DATA + 0x20_7000;

    pub(crate) const OC905_WORLD: u32 = DATA + 0x20_2000;

    pub(crate) const OC905_LOC: u32 = DATA + 0x20_3000;

    pub(crate) const OC905_LOC_VT: u32 = DATA + 0x20_4000;

    pub(crate) const OC905_NAME: u32 = DATA + 0x20_5000;

    /// Test control words: +0/+4 mask of call indices that return 0, +8 the
    /// lobby flag, +0xc name length, +0x10.. the four `info` words.
    pub(crate) const OC905_CTRL: u32 = DATA + 0x20_6000;

    /// The machine's miss hook: the logging fake, plus what the real callees
    /// leave in memory (name string, lobby flag, `info`) and a per-call mask
    /// that makes a call return 0 (null text objects, empty lobby).
    pub(crate) fn oc905_miss(c: &mut Cpu, target: u32) {
        let a0 = c.g[A0][0] as u32;
        let a2 = c.g[A2][0] as u32;
        let n = c.bus.read32(LOG_COUNT);
        fake_call(c, target);
        match target {
            0x0031_82d8 => {
                let len = c.bus.read32(OC905_CTRL + 0xc);
                c.bus.write32(a0, OC905_NAME);
                c.bus.write32(OC905_NAME - 8, len);
            }
            0x0025_f1e0 => {
                let flag = c.bus.read32(OC905_CTRL + 8);
                c.bus.write32(a2, flag);
            }
            0x0025_f288 => {
                for i in 0..4 {
                    let v = c.bus.read32(OC905_CTRL + 0x10 + 4 * i);
                    c.bus.write32(a2 + 4 * i, v);
                }
            }
            _ => {}
        }
        if n < 64 {
            let mask = c.bus.read32(OC905_CTRL + 4 * (n / 32));
            if mask >> (n % 32) & 1 != 0 {
                c.g[V0][0] = 0;
            }
        }
    }

    /// `ShowPlayerInfo`: every branch (no screen, empty lobby, invalid index,
    /// null text objects, lobby flag, win ratio below/at/above 100%, blank
    /// rows) and unwinds in the calls.
    #[test]
    fn c_fe_state_chat_room_show_player_info_matches() {
        fakes::covered(
            ee::s03::f_001b27b0__generated,
            c_fe_state_chat_room_show_player_info,
            240,
            &|c, seed| {
                let mut r = fakes::machine(c, seed, 0x1b27b0, 4);
                c.hooks.miss = oc905_miss;
                c.pc = 0x001b_27b0;
                c.g[A0][0] = sx(OC905_SELF);
                c.g[A1][0] = match seed % 4 {
                    0 => 0x0090_0000,
                    _ => (r.next_u32() % 8) as u64,
                };
                c.bus.write32(
                    OC905_SELF + SHOW_PLAYER_INFO_SCREEN,
                    if seed % 7 == 0 { 0 } else { OC905_SCREEN },
                );
                c.bus.write32(GAME_GP.wrapping_sub(0x848), OC905_WORLD);
                c.bus.write32(OC905_WORLD + 0x8c, OC905_LOC);
                c.bus.write32(OC905_LOC + 4, OC905_LOC_VT);
                c.bus.write16(OC905_LOC_VT + 0x20, 0);
                c.bus.write32(OC905_LOC_VT + 0x24, 0x0014_06c0);
                let (m0, m1) = if seed % 5 == 0 {
                    (0, 0)
                } else {
                    (
                        r.next_u32() & r.next_u32() & r.next_u32() & r.next_u32(),
                        r.next_u32() & r.next_u32() & r.next_u32() & r.next_u32(),
                    )
                };
                c.bus.write32(OC905_CTRL, m0);
                c.bus.write32(OC905_CTRL + 4, m1);
                c.bus.write32(OC905_CTRL + 8, (seed / 2) % 2);
                c.bus.write32(
                    OC905_CTRL + 0xc,
                    if seed % 3 == 0 {
                        0
                    } else {
                        1 + r.next_u32() % 9
                    },
                );
                let wins = r.next_u32() % 6;
                let games = match seed % 3 {
                    0 => wins,
                    1 => wins + 1 + r.next_u32() % 5,
                    _ => r.next_u32() % 6,
                };
                c.bus.write32(OC905_CTRL + 0x10, r.next_u32() & 0xfff);
                c.bus.write32(OC905_CTRL + 0x14, wins);
                c.bus.write32(OC905_CTRL + 0x18, games);
                c.bus.write32(OC905_CTRL + 0x1c, r.next_u32());
            },
        );
    }

    /// Gate word, widget mask / lookup counter and the call log hash (the fakes' state).
    pub(crate) const OC906_CTRL: u32 = DATA + 0x5000;

    pub(crate) const OC906_MAGIC: u32 = 0x0906_0906;

    /// The `cFEStateStats` object, the screen, one widget and its vtable.
    pub(crate) const OC906_SELF: u32 = DATA + 0x100;

    pub(crate) const OC906_SCREEN: u32 = DATA + 0x6000;

    pub(crate) const OC906_WIDGET: u32 = DATA + 0x2000;

    pub(crate) const OC906_VT: u32 = DATA + 0x3000;

    pub(crate) static OC906_PREV_FIND: AtomicUsize = AtomicUsize::new(0);

    pub(crate) static OC906_PREV_EVENT: AtomicUsize = AtomicUsize::new(0);

    pub(crate) static OC906_PREV_FILL: AtomicUsize = AtomicUsize::new(0);

    pub(crate) static OC906_PREV_RESET: AtomicUsize = AtomicUsize::new(0);

    pub(crate) static OC906_PREV_TEXT: AtomicUsize = AtomicUsize::new(0);

    /// Fold a fake call (target, a0, a1) into the log hash both sides must agree on.
    pub(crate) fn oc906_log(c: &mut Cpu, target: u32) {
        let h = c.bus.read32(OC906_CTRL + 0x20) as u64;
        let x = fakes::mix(h ^ (target as u64) << 32 ^ c.g[A0][0] ^ c.g[A1][0].rotate_left(21));
        c.bus.write32(OC906_CTRL + 0x20, x as u32);
        c.g[V0][0] = (x & 0xff) as u64;
        c.cycles += 7;
        ret(c);
    }

    /// `cUIScreen_getObjectByHashName` (0x39d860): lookup k returns the widget when bit k of
    /// the mask is set, else null.
    pub(crate) fn oc906_fake_find(c: &mut Cpu) {
        if c.bus.read32(OC906_CTRL) != OC906_MAGIC {
            return fakes::fall_back(c, &OC906_PREV_FIND, ee::s13::f_0039d860__generated);
        }
        let k = c.bus.read32(OC906_CTRL + 8);
        c.bus.write32(OC906_CTRL + 8, k + 1);
        let mask = c.bus.read32(OC906_CTRL + 4);
        c.g[V0][0] = if k < 32 && (mask >> k) & 1 != 0 {
            OC906_WIDGET as u64
        } else {
            0
        };
        c.cycles += 5;
        ret(c);
    }

    pub(crate) fn oc906_fake_event(c: &mut Cpu) {
        if c.bus.read32(OC906_CTRL) != OC906_MAGIC {
            return fakes::fall_back(c, &OC906_PREV_EVENT, ee::s03::f_001c4538__generated);
        }
        oc906_log(c, 0x001c_4538)
    }

    pub(crate) fn oc906_fake_fill(c: &mut Cpu) {
        if c.bus.read32(OC906_CTRL) != OC906_MAGIC {
            return fakes::fall_back(c, &OC906_PREV_FILL, ee::s03::f_001c47a8__generated);
        }
        oc906_log(c, 0x001c_47a8)
    }

    pub(crate) fn oc906_fake_reset(c: &mut Cpu) {
        if c.bus.read32(OC906_CTRL) != OC906_MAGIC {
            return fakes::fall_back(c, &OC906_PREV_RESET, ee::s03::f_001c4b78__generated);
        }
        oc906_log(c, 0x001c_4b78)
    }

    pub(crate) fn oc906_fake_text(c: &mut Cpu) {
        if c.bus.read32(OC906_CTRL) != OC906_MAGIC {
            return fakes::fall_back(c, &OC906_PREV_TEXT, ee::s13::f_003a1000__generated);
        }
        oc906_log(c, 0x003a_1000)
    }

    /// `cFEStateStats_SelectCategory(self, mode)`: the modes 0, 1, 2 and others, with and
    /// without a screen, with the mode changed or not, and with each subset of the widgets
    /// found (the lookup mask), the callees stood in by logging fakes and a widget whose
    /// colour and visibility slots are a real leaf.
    #[test]
    fn cfe_state_stats_select_category_matches() {
        fakes::hook(
            addr_of_mut!(ee::s13::OVERRIDE_0039D860),
            oc906_fake_find,
            &OC906_PREV_FIND,
        );
        fakes::hook(
            addr_of_mut!(ee::s03::OVERRIDE_001C4538),
            oc906_fake_event,
            &OC906_PREV_EVENT,
        );
        fakes::hook(
            addr_of_mut!(ee::s03::OVERRIDE_001C47A8),
            oc906_fake_fill,
            &OC906_PREV_FILL,
        );
        fakes::hook(
            addr_of_mut!(ee::s03::OVERRIDE_001C4B78),
            oc906_fake_reset,
            &OC906_PREV_RESET,
        );
        fakes::hook(
            addr_of_mut!(ee::s13::OVERRIDE_003A1000),
            oc906_fake_text,
            &OC906_PREV_TEXT,
        );
        check(
            ee::s03::f_001c3ee8__generated,
            cfe_state_stats_select_category,
            400,
            &|c, seed| {
                let mut r = machine(c, seed, 0x906, 0);
                elf_image(c);
                let mode = [0u32, 1, 2, 3, 4, 2, 1, 0][(seed % 8) as usize];
                let old = if seed % 3 == 0 { mode } else { mode ^ 1 };
                c.bus.write32(OC906_SELF + 0x6e0, old);
                let screen = if seed % 11 == 0 { 0 } else { OC906_SCREEN };
                c.bus.write32(OC906_SELF + 0x40, screen);
                c.bus.write32(OC906_WIDGET + 8, OC906_VT);
                c.bus.write16(OC906_VT + 0x58, 0);
                c.bus.write16(OC906_VT + 0x48, 0);
                c.bus.write32(OC906_VT + 0x5c, 0x0014_06c0);
                c.bus.write32(OC906_VT + 0x4c, 0x0014_06c0);
                let mask = match seed % 4 {
                    0 => 0xffff_ffff,
                    _ => r.next_u32(),
                };
                c.bus.write32(OC906_CTRL, OC906_MAGIC);
                c.bus.write32(OC906_CTRL + 4, mask);
                c.bus.write32(OC906_CTRL + 8, 0);
                c.bus.write32(OC906_CTRL + 0x20, 0);
                c.g[A0][0] = sx(OC906_SELF);
                c.g[A1][0] = mode as u64;
                c.pc = 0x001c_3ee8;
            },
        );
    }

    pub(crate) const SELF: u32 = DATA + 0x1000;

    pub(crate) const LIST_A: u32 = DATA + 0x3400;

    pub(crate) const LIST_V: u32 = DATA + 0x3800;

    pub(crate) const LIST_EV: u32 = DATA + 0x3c00;

    pub(crate) const GATE: u32 = DATA + 0x3f00;

    pub(crate) const MAGIC: u32 = 0x0907_f00d;

    /// Gated fake of `__builtin_delete` (0x317e50): the real one takes a
    /// semaphore and waits forever on a test machine.
    pub(crate) fn fake_delete(c: &mut Cpu) {
        if c.bus.read32(GATE) != MAGIC {
            return crate::difftest::fakes::fall_back(
                c,
                crate::difftest::fakes::prev_cell(fake_delete),
                ee::s10::f_00317e50__generated,
            );
        }
        c.cycles += 5;
        c.g[V0][0] = 0;
        crate::abi::ret(c);
    }

    pub(crate) fn install_fake_delete() {
        crate::difftest::fakes::hook(
            std::ptr::addr_of_mut!(ee::s10::OVERRIDE_00317E50),
            fake_delete,
            crate::difftest::fakes::prev_cell(fake_delete),
        );
    }

    /// A state object at `SELF` with a vtable (slots `0xc0 0xd8 0xf0 0xf8`
    /// call the fake; the 0xf0 slot sometimes runs a real leaf returning 0).
    pub(crate) fn net_state(c: &mut Cpu, r: &mut crate::difftest::Rng, seed: u32) {
        let vt = fakes::vtable(c, r, &[0xc0, 0xd8, 0xf0, 0xf8]);
        c.bus.write32(SELF + 8, vt);
        if seed % 2 == 1 {
            c.bus.write32(vt + 0xf4, 0x0014_06c0);
        }
        c.bus.write32(SELF + 0x10, DATA + 0x6000);
        // Child state at +0x20 (default branch of HandleNetEvent) and the
        // popup slot at +0x69c / +0x6a0.
        c.bus
            .write32(SELF + 0x20, if seed % 5 == 0 { 0 } else { SELF + 0x400 });
        c.bus.write32(SELF + 0x408, vt);
        c.bus.write32(crate::difftest::GAME_GP + 0x238, 0);
    }

    /// `NetFEState_OnNetEvent`: dispatches a network event: the login events
    /// (0x115/0x116), the queue case (0x114), a pending-event list drained
    /// through the jump table, or a plain forward to the state's handler.
    #[test]
    fn net_fe_state_on_net_event_matches() {
        install_fake_delete();
        check(
            ee::s03::f_001a8b88__generated,
            net_fe_state_on_net_event,
            160,
            &|c, seed| {
                let mut r = fakes::machine_rt(c, seed, 0x0907_0001, 3);
                c.pc = 0x001a_8b88;
                c.bus.write32(GATE, MAGIC);
                net_state(c, &mut r, seed);
                let ev = match seed % 8 {
                    0 => 0x115,
                    1 => 0x116,
                    2 => 0x114,
                    3 => 0x10,
                    _ => 0xc8 + (seed / 8) % 0x4f,
                };
                c.g[A0][0] = SELF as u64;
                c.g[A1][0] = ev as u64;
                c.g[A2][0] = (DATA + 0x2000) as u64;
                c.bus.write32(SELF + 0x6b4, (seed / 3) % 2);
                c.bus
                    .write32(SELF + 0x1c, if seed % 3 == 0 { 0 } else { 6 });
                c.bus
                    .write32(SELF + 0x6a0, if seed % 4 == 0 { 0 } else { SELF + 0x800 });
                // Pending list: empty (seed even) or one item whose event
                // code walks the 0xec.. jump table.
                // SELF+0x6c8 is the list header, SELF+0x6cc its circular
                // sentinel node (LIST_A): empty when the first node is the
                // sentinel itself, else one item V (next and prev: the
                // sentinel) whose unlink makes it empty again.
                c.bus.write32(SELF + 0x6cc, LIST_A);
                if seed % 2 == 0 {
                    c.bus.write32(LIST_A, LIST_A);
                    c.bus.write32(LIST_A + 4, LIST_A);
                } else {
                    c.bus.write32(LIST_A, LIST_V);
                    c.bus.write32(LIST_A + 4, LIST_V);
                    c.bus.write32(LIST_V, LIST_A);
                    c.bus.write32(LIST_V + 4, LIST_A);
                    c.bus.write32(LIST_V + 8, LIST_EV);
                    c.bus.write32(LIST_EV, 0xec + (seed / 2) % 0x2c);
                }
            },
        );
    }

    /// `NetFEState_HandleNetEvent`: the 0xdc.. network event jump table
    /// (popups, lobby and online menus, state change, timeout) with a
    /// forward to the child state for everything else.
    #[test]
    fn net_fe_state_handle_net_event_matches() {
        check(
            ee::s03::f_001a8e40__generated,
            net_fe_state_handle_net_event,
            160,
            &|c, seed| {
                let mut r = fakes::machine_rt(c, seed, 0x0907_0002, 2);
                c.pc = 0x001a_8e40;
                net_state(c, &mut r, seed);
                c.g[A0][0] = SELF as u64;
                c.g[A1][0] = (0xdc + seed % 0x40) as u64;
                c.g[A2][0] = (DATA + 0x2000) as u64;
                // The "time" tag of the timeout case.
                c.bus.write32(
                    DATA + 0x2008,
                    if seed % 3 == 0 { 0x7469_6d65 } else { 0x1234 },
                );
            },
        );
    }

