                let _r = oc912_machine(c, seed, 0x912_5d58, 2);
                let popup = DATA + 0x1100;
                let k = seed % 0x3c;
                let misc = if k >= 0x3a { 0x800 + k } else { 0x80e + k };
                c.bus.write32(popup + 0x18, misc);
