    #[test]
    fn c_fe_state_chat_room_init_matches() {
        oc918_install_fakes();
        check(
            ee::s03::f_001b2070__generated,
            c_fe_state_chat_room_init,
            24,
            &|c, seed| {
                let h0 = oc918_hash(c, DATA + 0x100);
                let mut r = oc918_base(c, seed, 0x1b20_70, 8);
                // CreateScreen returns null (early exit) or the screen.
                oc918_w(
                    c,
                    OC918_CTRL + 4,
                    if seed % 4 == 0 { 0 } else { OC918_SCREEN },
                );
                oc918_node(c, OC918_NODES, if seed % 4 == 2 { h0 ^ 1 } else { h0 });
                oc918_screen(c, OC918_SCREEN, &[OC918_NODES]);
                oc918_w(c, GAME_GP.wrapping_sub(0xc8), OC918_LOBBY);
                fill(c, &mut r, OC918_LOBBY, 0x40);
                let this = OC918_SELF;
                fill(c, &mut r, this, 0x1c0);
                oc918_w(c, this + 0x10, OC918_ARG);
                oc918_w(c, this + 0x6ec, DATA + 0x6000);
                oc918_w(c, this + 0x6f0, DATA + 0x6200);
                oc918_w(c, this + 0x6f4, DATA + 0x6400);
                c.g[A0][0] = this as u64;
            },
        );
    }

    /// Own gate word, magic and forced-result mailbox of the oc919 fakes
    /// (not the `fa_*` ones: both sets hook the same override slots).
    pub(crate) const OC919_CTRL: u32 = DATA + 0x2b_0000;
    pub(crate) const OC919_MAGIC: u32 = 0x0c91_95ed;
    pub(crate) const OC919_MAIL: u32 = DATA + 0x2c_0000;

    fn oc919_mail(addr: u32) -> u32 {
        OC919_MAIL + ((addr & 0xffff) >> 3) * 8
    }

    /// Make the oc919 fake of `addr` return `v` (sign-extended) in `v0`.
    pub(crate) fn oc919_force(c: &mut Cpu, addr: u32, v: u32) {
        let mail = oc919_mail(addr);
        c.bus.write32(mail, 1);
        c.bus.write32(mail + 4, v);
    }

    /// Like `fakes::fake_call`, then the forced result unless it unwound.
    fn oc919_fake_call(c: &mut Cpu, addr: u32) {
        let ra = c.g[RA][0] as u32;
        let mail = oc919_mail(addr);
        let mode = c.bus.read32(mail);
        let val = c.bus.read32(mail + 4);
        fakes::fake_call(c, addr);
        if c.pc == ra && mode == 1 {
            c.g[V0][0] = sx(val);
        }
    }

    /// Gated fakes (like `feasyncfile`'s `fa_*`): while the machine's RAM
    /// holds `OC919_MAGIC` at `OC919_CTRL` they log the call and return as
    /// `fakes::fake_call` does; otherwise they run the body they replaced.
    macro_rules! oc919_fakes {
        ($(($fake:ident, $slot:expr, $gen:path, $addr:expr)),* $(,)?) => {
            $(
                fn $fake(c: &mut Cpu) {
                    if c.bus.read32(OC919_CTRL) != OC919_MAGIC {
                        return fakes::fall_back(c, fakes::prev_cell($fake), $gen);
                    }
                    oc919_fake_call(c, $addr);
                }
            )*
            fn oc919_install_fakes() {
                $( fakes::hook(addr_of_mut!($slot), $fake, fakes::prev_cell($fake)); )*
                fakes::hook(
                    addr_of_mut!(ee::s06::OVERRIDE_0025F1E0),
                    oc919_fake_player_entry,
                    fakes::prev_cell(oc919_fake_player_entry),
                );
            }
        };
    }

