    /// `StoreEditedMessage`: slot index at or above 10 (nothing), below 10
    /// with the slot already filled (`0x416810` non-zero) and empty (popup
    /// built), fakes that unwind anywhere.
    #[test]
    fn c_fe_state_net_quick_messages_store_edited_message_matches() {
        fakes::covered(
            ee::s03::f_001c2a18__generated,
            c_fe_state_net_quick_messages_store_edited_message,
            120,
            &|c, seed| {
                let mut r = oc926_machine(c, seed, 0x926_2a18, 12, 0x001c_2a18);
                let variant = seed % 4;
                let index = if variant == 0 {
                    10 + seed % 7
                } else {
                    seed % 10
                };
                c.bus.write32(OC926_SELF + 0x69c, OC926_OBJ);
                c.bus.write32(OC926_OBJ + 0x18, index);
                // call 1: BELibrary_GetInterface -> the editor object (vtable at +0xc)
                oc926_force(c, 1, OC926_OBJ + 0x1000);
                oc926_object(c, &mut r, OC926_OBJ + 0x1000, OC926_VT, 0xc, &[8]);
                // call 2: the slot already holds a message?
                oc926_force(c, 2, (variant % 2 == 1) as u32);
                // call 3: GetPopup (an object the function writes into)
                oc926_force(c, 3, OC926_OBJ + 0x2000);
                c.g[A0][0] = sx(OC926_SELF);
            },
        );
    }

    /// `UpdateScrollBar`: no screen, `pos < 0`, `count < pos`, `count <= 0`,
    /// count 1 and larger, and the track / thumb widgets found or missing.
    #[test]
    fn c_fe_state_stats_update_scroll_bar_matches() {
        const ARGS: [(u32, u32); 7] = [
            (u32::MAX, 5),
            (6, 5),
            (0, 0),
            (0, 1),
            (1, 1),
            (2, 5),
            (4, 8),
        ];
        const FLOATS: [u32; 5] = [
            0x0000_0000,
            0x3fc0_0000,
            0xc050_0000,
            0x42c8_0000,
            0x4930_d400,
        ];
        fakes::covered(
            ee::s03::f_001c3d68__generated,
            c_fe_state_stats_update_scroll_bar,
            168,
            &|c, seed| {
                let mut r = oc926_machine(c, seed, 0x926_3d68, 8, 0x001c_3d68);
                let (pos, count) = ARGS[seed as usize % ARGS.len()];
                let variant = seed / 7;
                c.bus.write32(
                    OC926_SELF + 0x40,
                    if variant % 8 == 7 { 0 } else { OC926_ZERO },
                );
                let track = OC926_OBJ;
                let thumb = OC926_OBJ + 0x1000;
                // call 1: the track, call 3: the thumb
                oc926_force(c, 1, if variant % 2 == 0 { track } else { 0 });
                oc926_force(c, 3, if variant / 2 % 2 == 0 { thumb } else { 0 });
                oc926_object(c, &mut r, track, OC926_VT, 8, &[0xa0, 0x48]);
                oc926_object(c, &mut r, thumb, OC926_VT + 0x400, 8, &[0x48]);
                for off in [0x44u32, 0x48, 0x4c] {
                    let f = FLOATS[r.next_u32() as usize % FLOATS.len()];
                    c.bus.write32(track + off, f);
                    c.bus.write32(thumb + off, r.next_u32());
                }
                // the float the track method leaves at sp+4 of the frame
                let f = FLOATS[r.next_u32() as usize % FLOATS.len()];
                c.bus.write32(crate::difftest::SP - 0x80 + 4, f);
                c.g[A0][0] = sx(OC926_SELF);
                c.g[A1][0] = sx(pos);
                c.g[A2][0] = sx(count);
            },
        );
    }

    /// `FillCourseList`: no list box, no second box, and the 29-entry table
    /// with matching / non-matching entries (first match kept, valid or
    /// invalid course id).
    #[test]
    fn c_fe_state_stats_fill_course_list_matches() {
        fakes::covered(
            ee::s03::f_001c49c8__generated,
            c_fe_state_stats_fill_course_list,
            220,
            &|c, seed| {
                let mut r = oc926_machine(c, seed, 0x926_49c8, 20, 0x001c_49c8);
                c.bus.write32(OC926_SELF + 0x40, OC926_ZERO);
                c.bus.write32(OC926_SELF + 0x6e0, 0x66);
                let widget = OC926_OBJ;
                // calls 1 and 6: UIScreen_FindObject; call 2: the selected value
                oc926_force(c, 1, if seed % 5 == 0 { 0 } else { widget });
                oc926_force(c, 2, 0x55);
                oc926_force(c, 6, if seed % 5 == 1 { 0 } else { widget });
                let none = seed % 11 == 0;
                for i in 0..29u32 {
                    let e = OC926_COURSES + 0x10 * i;
                    let id = (r.next_u32() % 45) as i32 - 8;
                    c.bus.write32(e, id as u32);
                    c.bus.write32(e + 4, r.next_u32());
                    let hit = !none && r.next_u32() % 3 == 0;
                    c.bus.write32(e + 8, if hit { 0x55 } else { 0x54 });
                    c.bus.write32(
                        e + 12,
                        if hit || r.next_u32() % 2 == 0 {
                            0x66
                        } else {
                            0x67
                        },
                    );
                }
                c.g[A0][0] = sx(OC926_SELF);
            },
        );
    }

    /// `PostInput`: every combination of the four button queries (per-call
    /// results from the seed bits) with `mode` below and above 3.
    #[test]
    fn c_fe_state_stats_post_input_matches() {
        fakes::covered(
            ee::s03::f_001c4bd8__generated,
            c_fe_state_stats_post_input,
            512,
            &|c, seed| {
                let mut r = oc926_machine(c, seed, 0x926_4bd8, 10, 0x001c_4bd8);
                let input = OC926_OBJ;
                oc926_object(c, &mut r, input, OC926_VT, 8, &[0x88, 0x90, 0xa0, 0x98]);
                for n in 0..8u32 {
                    // calls 1..8 are the queries (call 0 is the base input)
                    c.bus.write32(
                        OC926_RES + 4 * (n + 1),
                        if seed >> n & 1 == 1 { 2 } else { 1 },
                    );
                }
                c.bus
                    .write32(OC926_SELF + 0x6e4, if seed >> 8 & 1 == 1 { 2 } else { 5 });
                c.g[A0][0] = sx(OC926_SELF);
                c.g[A1][0] = sx(input);
            },
        );
    }

    /// Gate word of the news fakes: they act only while the magic is in RAM.
    pub(crate) const NEWS_CTRL: u32 = DATA + 0x20_0300;

    pub(crate) const NEWS_MAGIC: u32 = 0x0927_5eed;

    /// The news panel, its event (`data`; the text is at +8), the item's
    /// string and the text scroller's object.
    pub(crate) const NEWS_SELF: u32 = DATA + 0x20_0400;

    pub(crate) const NEWS_EVENT: u32 = DATA + 0x20_0600;

    pub(crate) const NEWS_STR: u32 = DATA + 0x20_0700;

    pub(crate) const NEWS_TEXT: u32 = DATA + 0x20_0800;

    pub(crate) fn news_gate(c: &mut Cpu) -> bool {
        c.bus.read32(NEWS_CTRL) == NEWS_MAGIC
    }

    /// `cUIScreen_getObjectByHashName` (0x39d860): the scroller for seeds
    /// that have one (word +4 of the gate: 1), else null.
    pub(crate) fn oc927_news_object(c: &mut Cpu) {
        if !news_gate(c) {
            return fakes::fall_back(
                c,
                fakes::prev_cell(oc927_news_object),
                ee::s13::f_0039d860__generated,
            );
        }
        let has_text = c.bus.read32(NEWS_CTRL + 4) != 0;
        fakes::fake_call(c, 0x0039_d860);
        c.g[V0][0] = if has_text { NEWS_TEXT as u64 } else { 0 };
    }

    /// `GetHashValue32` (0x317670): the plain fake.
    pub(crate) fn oc927_news_hash(c: &mut Cpu) {
        if !news_gate(c) {
            return fakes::fall_back(
                c,
                fakes::prev_cell(oc927_news_hash),
                ee::s10::f_00317670__generated,
            );
        }
        fakes::fake_call(c, 0x0031_7670);
    }

    /// `cBXString` copy constructor (0x317fe8): copies the source's string
    /// pointer (the strings are shared; setAt writes through them).
    pub(crate) fn oc927_news_copy(c: &mut Cpu) {
        if !news_gate(c) {
            return fakes::fall_back(
                c,
                fakes::prev_cell(oc927_news_copy),
                ee::s10::f_00317fe8__generated,
            );
        }
        let obj = c.g[A0][0] as u32;
        let src = c.g[A1][0] as u32;
        let s = c.bus.read32(src);
        c.bus.write32(obj, s);
        fakes::fake_call(c, 0x0031_7fe8);
    }

    /// `cBXString::find` (0x318c18): the index of byte a1 from a2 in the
    /// NUL-terminated string at word 0 of the object, or -1.
    pub(crate) fn oc927_news_find(c: &mut Cpu) {
        if !news_gate(c) {
            return fakes::fall_back(
                c,
                fakes::prev_cell(oc927_news_find),
                ee::s10::f_00318c18__generated,
            );
        }
        let obj = c.g[A0][0] as u32;
        let ch = c.g[A1][0] as u8;
        let from = c.g[A2][0] as u32;
        let s = c.bus.read32(obj);
        let mut found = u64::MAX;
        for i in from..from + 64 {
            let b = c.bus.read8(s + i);
            if b == 0 {
                break;
            }
            if b == ch {
                found = i as u64;
                break;
            }
        }
        fakes::fake_call(c, 0x0031_8c18);
        c.g[V0][0] = found;
    }

    /// `cBXString::setAt` (0x318e68): stores a2 at index a1 of the string.
    pub(crate) fn oc927_news_set_at(c: &mut Cpu) {
        if !news_gate(c) {
            return fakes::fall_back(
                c,
                fakes::prev_cell(oc927_news_set_at),
                ee::s10::f_00318e68__generated,
            );
        }
        let obj = c.g[A0][0] as u32;
        let idx = c.g[A1][0] as u32;
        let ch = c.g[A2][0] as u8;
        let s = c.bus.read32(obj);
        c.bus.write8(s.wrapping_add(idx), ch);
        fakes::fake_call(c, 0x0031_8e68);
    }

    /// `cBXString::~cBXString` (0x318260): the plain fake.
    pub(crate) fn oc927_news_dtor(c: &mut Cpu) {
        if !news_gate(c) {
            return fakes::fall_back(
                c,
                fakes::prev_cell(oc927_news_dtor),
                ee::s10::f_00318260__generated,
            );
        }
        fakes::fake_call(c, 0x0031_8260);
    }

    /// `NetFEState_HandleNetEvent` (0x1a8e40): the plain fake.
    pub(crate) fn oc927_news_handle(c: &mut Cpu) {
        if !news_gate(c) {
            return fakes::fall_back(
                c,
                fakes::prev_cell(oc927_news_handle),
                ee::s03::f_001a8e40__generated,
            );
        }
        fakes::fake_call(c, 0x001a_8e40);
    }

    pub(crate) fn oc927_news_install() {
        fakes::hook(
            addr_of_mut!(ee::s13::OVERRIDE_0039D860),
            oc927_news_object,
            fakes::prev_cell(oc927_news_object),
        );
        fakes::hook(
            addr_of_mut!(ee::s10::OVERRIDE_00317670),
            oc927_news_hash,
            fakes::prev_cell(oc927_news_hash),
        );
        fakes::hook(
            addr_of_mut!(ee::s10::OVERRIDE_00317FE8),
            oc927_news_copy,
            fakes::prev_cell(oc927_news_copy),
        );
        fakes::hook(
            addr_of_mut!(ee::s10::OVERRIDE_00318C18),
            oc927_news_find,
            fakes::prev_cell(oc927_news_find),
        );
        fakes::hook(
            addr_of_mut!(ee::s10::OVERRIDE_00318E68),
            oc927_news_set_at,
            fakes::prev_cell(oc927_news_set_at),
        );
        fakes::hook(
            addr_of_mut!(ee::s10::OVERRIDE_00318260),
            oc927_news_dtor,
            fakes::prev_cell(oc927_news_dtor),
        );
        fakes::hook(
            addr_of_mut!(ee::s03::OVERRIDE_001A8E40),
            oc927_news_handle,
            fakes::prev_cell(oc927_news_handle),
        );
    }

    /// The news panel for `seed`: message 226 (every fourth seed another),
    /// a scroller for four seeds in five, and a 48-character text of newlines
    /// and letters (single and doubled newlines both occur).
    pub(crate) fn news_fixture(c: &mut Cpu, seed: u32, r: &mut Rng) {
        c.bus.write32(NEWS_CTRL, NEWS_MAGIC);
        c.bus.write32(NEWS_CTRL + 4, (seed % 5 != 0) as u32);
        c.bus.write32(NEWS_EVENT + 8, NEWS_STR);
        const ALPHABET: [u8; 5] = [b'\n', b'\n', b'x', b' ', b'\n'];
        for i in 0..48u32 {
            let ch = ALPHABET[(r.next_u32() % 5) as usize];
            c.bus.write8(NEWS_STR + i, ch);
        }
        c.bus.write8(NEWS_STR + 48, 0);
        c.g[A0][0] = sx(NEWS_SELF);
        c.g[A1][0] = if seed % 4 == 0 { 0xe1 } else { 0xe2 };
        c.g[A2][0] = sx(NEWS_EVENT);
        c.pc = 0x001c_5430;
    }

    #[test]
    fn cfe_state_net_news_v31_matches() {
        oc927_news_install();
        check(
            ee::s03::f_001c5430__generated,
            cfe_state_net_news_v31,
            300,
            &|c, seed| {
                let mut r = fakes::machine_rt(c, seed, 0x927_0003, 6);
                news_fixture(c, seed, &mut r);
            },
        );
    }

